INSERT INTO feature VALUES('lazy-records','types','Lazy records (negative products)',NULL,'implemented','notable',NULL,'A computation record of components evaluated on projection, with its η rule, persisted by the kernel; it is written at its positions, or at its labels in any order against a lazy record its definition''s signature, an annotation or its body''s answer states; an entry is observed by its position, `m.i`, against a stated lazy record, lazy product chain or codata family, and a parameter''s observation prints as `a.i`.','core-checker core-incremental core-nbe core-sequent core-term kernel-core kernel-term runtime-stencils surface-format surface-lowering surface-pretty','corpus/surface/arity/lazy-record.gandr corpus/pathological/codata/lazy-record-projection.gandr corpus/pathological/type-associativity.gandr corpus/model/codata/codata-observations.gandr','corpus/model/codata/codata-observations.gandr',NULL);
